def feature(s):
    if not s:
        return 0.0
    p = s.get('element_properties') or {}
    sites = s.get('sites') or []
    volume = (s.get('lattice') or {}).get('volume_A3')
    if volume is None or volume <= 0:
        v = s.get('volume_per_atom_A3')
        count = sum(max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites)
        volume = v * count if v is not None and v > 0 else 0.0
    if volume <= 0:
        return 0.0
    total = 0.0
    for a in sites:
        r = (p.get(a.get('element')) or {}).get('covalent_radius_A')
        if r is not None and r > 0:
            total += max(a.get('occupancy', 1.0) or 0.0, 0.0) * r * r * r
