def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    nearest = [None for a in sites]
    edges = []
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and occ[i] > 0 and occ[j] > 0:
            edges += [(i, j, d)]
            if nearest[i] is None or d < nearest[i]:
                nearest[i] = d
    total = 0.0
    for i, j, d in edges:
        t = d / nearest[i]
        if t <= 2.0:
            total += occ[i] * occ[j] * exp(1.0 - t ** 6)
    return total / weight

