    counts = {}
    for i in range(n):
        if r[i] is not None and r[i] > 0 and occ[i] > 0:
            e = sites[i].get('element')
            counts[e] = counts.get(e, 0.0) + occ[i]
    mass = sum(counts.values())
    if mass <= 0:
        return 0.0
    same = 0.0
    total = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8:
            if r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0:
                w = occ[i] * occ[j] * max(1.5 - d / (r[i] + r[j]), 0.0) ** 2
                total += w
                if sites[i].get('element') == sites[j].get('element'):
                    same += w
    return same / total - sum((x / mass) ** 2 for x in counts.values()) if total > 0 else 0.0

