def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    r = [(p.get(a.get('element')) or {}).get('covalent_radius_A') for a in sites]
    en = [(p.get(a.get('element')) or {}).get('eneg') for a in sites]
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    weights = [0.0 for a in sites]
    contrasts = [0.0 for a in sites]
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8:
            if r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0 and en[i] is not None and en[j] is not None:
                w = occ[j] * max(1.5 - d / (r[i] + r[j]), 0.0) ** 2
                weights[i] += w
                contrasts[i] += w * (en[j] - en[i])
    weight = sum(occ[i] for i in range(n) if weights[i] > 0)
    if weight <= 0:
        return 0.0
    return sqrt(sum(occ[i] * (contrasts[i] / weights[i]) ** 2 for i in range(n) if weights[i] > 0) / weight)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    matrix = (s.get('lattice') or {}).get('matrix')
    if matrix is None or len(matrix) != 3:
        return 0.0
    p = s.get('element_properties') or {}
    r = [(p.get(a.get('element')) or {}).get('covalent_radius_A') for a in sites]
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    tensor = np.zeros((3, 3))
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and occ[i] > 0 and occ[j] > 0:
            if r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0:
                w = occ[i] * occ[j] * max(1.35 - d / (r[i] + r[j]), 0.0) ** 2
                fi = sites[i].get('frac_coords')
                fj = sites[j].get('frac_coords')
                image = b.get('image')
                if w > 0 and fi is not None and fj is not None and image is not None:
                    f = [fj[k] + image[k] - fi[k] for k in range(3)]
                    v = np.array([sum(f[k] * matrix[k][a] for k in range(3)) for a in range(3)])
                    tensor += (w / (d * d)) * v.reshape(3, 1) * v.reshape(1, 3)
    trace = float(np.trace(tensor))
    if trace <= 0:
        return 0.0
    eigenvalues = np.linalg.eigvalsh(tensor)
    return min(max(3.0 * float(eigenvalues[0]) / trace, 0.0), 1.0)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    r = [(p.get(a.get('element')) or {}).get('covalent_radius_A') for a in sites]
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    weight = sum(occ)
    if weight <= 0:
        return 0.0
    adjacency = [[] for a in sites]
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        image = b.get('image')
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and occ[i] > 0 and occ[j] > 0 and image is not None:
            if r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0 and d <= 1.25 * (r[i] + r[j]):
                adjacency[i] += [(j, tuple(image))]
    shifts = [None for a in sites]
    total = 0.0
    for root in range(n):
        if shifts[root] is not None or occ[root] <= 0:
            continue
        shifts[root] = (0, 0, 0)
        queue = [root]
        cursor = 0
        mass = 0.0
        gram = np.zeros((3, 3))
        while cursor < len(queue):
            i = queue[cursor]
            cursor += 1
            mass += occ[i]
            for j, image in adjacency[i]:
                proposed = tuple(shifts[i][k] + image[k] for k in range(3))
                if shifts[j] is None:
                    shifts[j] = proposed
                    queue += [j]
                else:
                    winding = [proposed[k] - shifts[j][k] for k in range(3)]
                    if any(winding):
                        for a in range(3):
                            for b in range(3):
                                gram[a, b] += winding[a] * winding[b]
        rank = sum(1 for value in np.linalg.eigvalsh(gram) if value > 1e-8)
        total += mass * rank
    return total / weight
